select if(whole > 0, whole, price) as i, case when whole > 0 then whole else 'none' end as c, coalesce(whole, price) as co, ifnull(whole, v) as ifn, nullif(whole, 1) as nf, greatest(whole, price) as g, least(whole, big) as l, coalesce(day, at) as dt, coalesce(day, t) as dtt, if(flag, day, v) as dv, coalesce(whole, doc) as wj, greatest(day, at) as gd, coalesce(f, whole) as fw, coalesce(tiny, big) as tb2, ifnull(utiny, ubig) as ub2 from everything
